import { forbidden } from 'next/navigation';
import { verifyAdmin } from '@/app/lib/auth';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: '2.5rem' }}>
      <h1 style={{ margin: 0, fontSize: '2rem' }}>Admin Dashboard</h1>
      <p style={{ marginTop: '0.75rem', color: '#444' }}>
        Welcome back{session?.name ? `, ${session.name}` : ''}.
      </p>
      <p style={{ marginTop: '0.5rem' }}>
        You have admin access to this protected area.
      </p>
    </main>
  );
}

